'use strict';

const crypto = require('node:crypto');
const { fields, array, text, identifier, publicHttps } = require('./validation.cjs');

const SELECT_KEYS = new Set(['task', 'globalPause', 'appReady', 'quota', 'humanStartedOnly']);
const HANDOFF_KEYS = new Set(['requestId', 'objective', 'sources', 'acceptance', 'stopCondition', 'timeBoundMinutes']);
const TASKS = new Set(['browser', 'research']);
const QUOTAS = new Set(['ready', 'exhausted', 'unknown']);
const GUARDS = Object.freeze([
  'Use only the named public HTTPS sources.',
  'Do not send messages, deploy, publish, purchase, change accounts, or access secrets.',
  'Do not start recurring or background work.',
  'Do not delegate beyond the coordinator-assigned packet.',
  'Return evidence candidates for local verification; never grant acceptance.',
]);

function selectBrowserFeature(input) {
  const source = fields(input, 'input', SELECT_KEYS);
  const task = source.get('task'), quota = source.get('quota'), humanStartedOnly = source.get('humanStartedOnly');
  if (!TASKS.has(task)) throw new TypeError('input.task: invalid');
  if (typeof source.get('globalPause') !== 'boolean' || typeof source.get('appReady') !== 'boolean') throw new TypeError('input pause/readiness: boolean required');
  if (!QUOTAS.has(quota)) throw new TypeError('input.quota: invalid');
  if (humanStartedOnly !== true && humanStartedOnly !== false && humanStartedOnly !== 'unknown') throw new TypeError('input.humanStartedOnly: invalid');
  const result = (status, reason) => ({ schema: 'agent-workbench-browser-selection-v1', feature: 'public-browser-assistant', status, action: status === 'eligible' ? 'prepare-public-handoff' : 'wait', reason, autostart: false, executed: false });
  if (source.get('globalPause')) return result('wait', 'global pause');
  if (!source.get('appReady')) return result('setup-required', 'browser assistant readiness is not caller-attested');
  if (quota !== 'ready') return result('wait', `quota=${quota}`);
  if (humanStartedOnly !== true) return result('wait', 'human-started-only state must be known true');
  return result('eligible', 'fresh caller-attested on-demand public handoff is eligible');
}

function buildPublicHandoff(input) {
  const source = fields(input, 'input', HANDOFF_KEYS);
  const requestId = identifier(source.get('requestId'), 'input.requestId');
  const objective = text(source.get('objective'), 'input.objective', 1000);
  const sources = array(source.get('sources'), 'input.sources', 5, 1).map((item, index) => publicHttps(item, `input.sources[${index}]`));
  const acceptance = array(source.get('acceptance'), 'input.acceptance', 5, 1).map((item, index) => text(item, `input.acceptance[${index}]`, 200));
  const stopCondition = text(source.get('stopCondition'), 'input.stopCondition', 200);
  const timeBoundMinutes = source.get('timeBoundMinutes');
  if (!Number.isInteger(timeBoundMinutes) || timeBoundMinutes < 1 || timeBoundMinutes > 15) throw new TypeError('input.timeBoundMinutes: invalid');
  const publicInputs = { requestId, objective, sources, acceptance, stopCondition, timeBoundMinutes };
  const binding = { schema: 'agent-workbench-public-handoff-v1', publicInputs, guards: GUARDS.slice() };
  const packetHash = crypto.createHash('sha256').update(JSON.stringify(binding)).digest('hex');
  const prompt = [
    `Request ID: ${requestId}`, `Objective: ${objective}`, `Public sources:\n${sources.map(item => `- ${item}`).join('\n')}`,
    `Acceptance:\n${acceptance.map(item => `- ${item}`).join('\n')}`, `Stop condition: ${stopCondition}`, `Time bound: ${timeBoundMinutes} minutes`,
    `Immutable guards:\n${GUARDS.map(item => `- ${item}`).join('\n')}`, `Return binding: requestId=${requestId}; packetHash=${packetHash}`,
    'Return a compact candidate with findings, source pointers, limitations, and any artifact hashes actually observed.',
  ].join('\n\n');
  if (prompt.length > 6000) throw new TypeError('handoff prompt exceeds bound');
  return { schema: 'agent-workbench-public-handoff-v1', status: 'prepared', dispatched: false, executed: false, requestId, packetHash, prompt, publicInputs, guards: GUARDS.slice(), autonomousRecurringWork: false };
}

module.exports = { selectBrowserFeature, buildPublicHandoff };

#!/usr/bin/env node
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { createStore } = require('../lib/index.cjs');

function usage() { return 'usage: agent-evolution <init|show|propose|register-evaluation|evidence|review|promote|rollback|export> --state FILE [--input FILE]'; }
function args(values) { const result = {}; for (let i = 0; i < values.length; i += 2) { const key = values[i]?.slice(2); if (!values[i]?.startsWith('--') || values[i + 1] === undefined || Object.hasOwn(result, key)) throw new Error(usage()); result[key] = values[i + 1]; } return result; }
function only(flags, allowed) { if (Object.keys(flags).some(key => !allowed.includes(key))) throw new Error(usage()); }
function input(file) { try { const stat = fs.lstatSync(file); if (stat.isSymbolicLink() || !stat.isFile() || stat.nlink > 1 || stat.size > 128 * 1024) throw new Error('unsafe'); return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { throw new Error('input must be a bounded unlinked regular JSON file'); } }
try {
  const [command, ...rest] = process.argv.slice(2); const flags = args(rest);
  if (!command || !flags.state) throw new Error(usage()); const store = createStore({ stateFile: flags.state }); let result;
  if (command === 'init') { only(flags, ['state', 'input']); result = store.init(flags.input ? input(flags.input) : {}); }
  else if (command === 'show') { only(flags, ['state']); result = store.readState(); }
  else if (command === 'rollback') { only(flags, ['state', 'version']); result = store.rollback({ version: flags.version }); }
  else if (command === 'export') { only(flags, ['state', 'destination', 'root']); result = store.exportActive({ destination: flags.destination, exportRoot: flags.root }); }
  else if (['propose', 'register-evaluation', 'evidence', 'review', 'promote'].includes(command)) { only(flags, ['state', 'input']); if (!flags.input) throw new Error(`${command} requires --input FILE`); const payload = input(flags.input); result = command === 'propose' ? store.propose(payload) : command === 'register-evaluation' ? store.registerEvaluation(payload) : command === 'evidence' ? store.recordEvidence(payload) : command === 'review' ? store.review(payload) : store.promote(payload); }
  else throw new Error(usage());
  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
} catch (error) { process.stderr.write(`agent-evolution: ${error.message}\n`); process.exitCode = 1; }
